*{box-sizing:border-box} :root{--bg:#0a0a13;--panel:#11111d;--line:#252536;--muted:#858498;--white:#f5f4fc;--purple:#a98bff;--pink:#ff77bd;--green:#87e8c1;font-family:'Space Grotesk',sans-serif;color:var(--white)}body{margin:0;min-height:100vh;background:radial-gradient(ellipse at 68% 28%,rgba(95,65,161,.12),transparent 36%),var(--bg);overflow-x:hidden}.app-shell{width:min(1200px,calc(100% - 72px));min-height:100vh;margin:auto;display:flex;flex-direction:column}.topbar{height:82px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.07);flex-shrink:0}.brand{font-weight:700;font-size:21px;letter-spacing:3px;color:var(--white);text-decoration:none;display:flex;align-items:center;gap:10px}.brand-dot{color:var(--purple)}.brand-mark{height:20px;display:flex;align-items:flex-end;gap:3px}.brand-mark i{width:3px;border-radius:4px;background:var(--purple);height:12px}.brand-mark i:nth-child(2){height:19px}.brand-mark i:nth-child(3){height:15px}.brand-mark i:nth-child(4){height:8px}.top-right{display:flex;align-items:center;gap:20px}.local-badge{font:10px 'DM Mono',monospace;letter-spacing:1.5px;color:#8f8d9f}.local-badge span,.live-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#7be4b7;box-shadow:0 0 10px #7be4b7;margin-right:8px}.icon-btn{width:34px;height:34px;border:1px solid var(--line);border-radius:50%;background:transparent;color:#aaa5c5;font-size:17px;cursor:pointer}.icon-btn.active{background:#a98bff;color:#15121f}.home-view{position:relative;flex:1;display:grid;grid-template-columns:1fr 1.05fr;grid-template-rows:minmax(430px,1fr) 107px;align-items:center;column-gap:60px}.hero-copy{padding:5px 0 0 16px}.eyebrow{display:flex;align-items:center;gap:10px;color:#aaa2c4;font:10px 'DM Mono',monospace;letter-spacing:2px}.eyebrow-line{width:23px;height:1px;background:var(--purple)}h1{font-size:clamp(54px,6.1vw,80px);line-height:.98;letter-spacing:-5px;margin:24px 0 20px;font-weight:600}h1 span{color:var(--purple)}.hero-sub{font-size:15px;line-height:1.8;color:#9997a9;max-width:435px;margin:0 0 29px}.hero-actions{display:flex;align-items:center;gap:22px;flex-wrap:wrap}.primary-btn{height:53px;padding:0 18px;border:0;border-radius:7px;background:var(--purple);color:#171222;font:600 14px 'Space Grotesk',sans-serif;cursor:pointer;transition:.2s;box-shadow:0 6px 26px rgba(169,139,255,.18);display:inline-flex;align-items:center;gap:12px}.primary-btn:hover{background:#bda8ff;transform:translateY(-2px);box-shadow:0 10px 28px rgba(169,139,255,.27)}.upload-icon{font-size:20px;font-weight:400}.btn-arrow{font-size:18px;margin-left:10px}.text-btn{border:0;background:none;color:#b9b6c8;font:500 13px 'Space Grotesk',sans-serif;cursor:pointer;padding:12px 0}.text-btn:hover{color:white}.play-small{color:var(--purple);font-size:10px;margin-right:8px}.format-note{font:10px 'DM Mono',monospace;color:#747286;letter-spacing:.3px;margin-top:18px}.format-note span{color:var(--purple);font-size:15px;vertical-align:-2px;margin-right:4px}.format-note b{font-weight:400;color:#514e60;margin:0 5px}.game-preview{position:relative;max-width:520px;width:100%;height:365px;margin:10px auto 0;background:linear-gradient(145deg,#141321,#10101a);border:1px solid #29263a;border-radius:13px;overflow:visible;box-shadow:0 25px 80px rgba(0,0,0,.24)}.preview-head{height:47px;border-bottom:1px solid #262536;padding:0 17px;display:flex;align-items:center;justify-content:space-between;color:#a49ebc;font:9px 'DM Mono',monospace;letter-spacing:1.1px}.preview-track{color:#625f74}.preview-bpm{color:#c6bbec;letter-spacing:.3px}.preview-board{height:278px;position:relative;overflow:hidden;background:linear-gradient(180deg,rgba(13,12,22,.15),rgba(8,8,15,.55))}.preview-glow{position:absolute;bottom:40px;height:115px;width:100%;background:linear-gradient(0deg,rgba(165,128,255,.13),transparent);pointer-events:none}.lane-divider{position:absolute;top:0;bottom:0;width:1px;background:rgba(255,255,255,.075);left:25%}.