.setup-view{flex:1;position:relative;padding:26px 0 38px}.back-btn{border:0;background:none;color:#aaa7b8;font:12px 'Space Grotesk',sans-serif;display:flex;align-items:center;gap:9px;cursor:pointer;padding:6px 0}.back-btn:first-letter{font-size:18px}.back-btn:hover{color:white}.setup-grid{max-width:920px;margin:24px auto 0;display:grid;grid-template-columns:330px 1fr;gap:58px;align-items:center}.track-art{height:390px;border-radius:12px;position:relative;overflow:hidden;background:radial-gradient(ellipse at 50% 45%,rgba(165,126,255,.35),transparent 40%),linear-gradient(145deg,#251d3d,#11111d 65%);border:1px solid #332a4d;box-shadow:0 22px 65px #06060b}.track-art:before,.track-art:after{content:'';position:absolute;background:linear-gradient(90deg,transparent,rgba(173,146,255,.35),transparent);height:1px;left:0;right:0;top:25%}.track-art:after{top:73%;opacity:.5}.art-orbit{position:absolute;border:1px solid rgba(193,169,255,.23);border-radius:50%;left:50%;top:46%;transform:translate(-50%,-50%)}.orbit-one{width:220px;height:220px}.orbit-two{width:300px;height:300px;border-color:rgba(193,169,255,.12)}.art-bars{height:86px;display:flex;gap:7px;align-items:center;justify-content:center;position:absolute;top:35%;left:0;right:0}.art-bars i{display:block;width:8px;border-radius:9px;background:linear-gradient(0deg,#a98bff,#f08bce);box-shadow:0 0 14px rgba(169,139,255,.4);animation:wave 1.1s ease-in-out infinite alternate}.art-bars i:nth-child(1),.art-bars i:nth-child(13){height:19px}.art-bars i:nth-child(2),.art-bars i:nth-child(12){height:37px;animation-delay:.2s}.art-bars i:nth-child(3),.art-bars i:nth-child(11){height:59px;animation-delay:.4s}.art-bars i:nth-child(4),.art-bars i:nth-child(10){height:75px;animation-delay:.1s}.art-bars i:nth-child(5),.art-bars i:nth-child(9){height:48px;animation-delay:.6s}.art-bars i:nth-child(6),.art-bars i:nth-child(8){height:64px;animation-delay:.3s}.art-bars i:nth-child(7){height:83px;animation-delay:.5s}@keyframes wave{to{transform:sc