59:   function detectBeats(buffer) {
60:     const sampleRate = buffer.sampleRate;
61:     const hop = Math.max(256, Math.floor(sampleRate * .01));
62:     const frames = Math.floor(buffer.length / hop);
63:     const channels = Array.from({ length: buffer.numberOfChannels }, (_, i) => buffer.getChannelData(i));
64:     const energy = new Float32Array(frames);
65:     for (let f = 0; f < frames; f++) {
66:       let sum = 0, start = f * hop, end = Math.min(start + hop, buffer.length);
67:       for (let c = 0; c < channels.length; c++) {
68:         const data = channels[c];
69:         for (let i = start; i < end; i += 4) sum += data[i] * data[i];
70:       }
71:       energy[f] = Math.sqrt(sum / Math.max(1, channels.length * ((end - start) / 4)));
72:     }
73:     const novelty = new Float32Array(frames);
74:     for (let i = 2; i < frames; i++) novelty[i] = Math.max(0, energy[i] - (energy[i - 1] * .72 + energy[i - 2] * .28));
75:     for (let i = 2; i < frames - 2; i++) novelty[i] = (novelty[i - 2] + novelty[i - 1] + novelty[i] * 2 + novelty[i + 1] + novelty[i + 2]) / 6;
76:     let bestLag = 50, bestScore = -1, runnerUp = 0;
77:     for (let lag = 33; lag <= 86; lag++) {
78:       let scoreAtLag = 0, count = 0;
79:       for (let i = lag; i < frames; i++) { scoreAtLag += novelty[i] * novelty[i - lag]; count++; }
80:       scoreAtLag /= Math.max(1, count);
81:       if (scoreAtLag > bestScore) { runnerUp = bestScore; bestScore = scoreAtLag; bestLag = lag; }
82:       else if (scoreAtLag > runnerUp) runnerUp = scoreAtLag;
83:     }
84:     let detectedBpm = Math.round(6000 / bestLag);
85:     if (detectedBpm < 70) detectedBpm *= 2;
86:     if (detectedBpm > 180) detectedBpm = Math.round(detectedBpm / 2);
87:     detectedBpm = Math.max(70, Math.min(180, detectedBpm));
88:     const interval = 60 / detectedBpm;
89:     const lag = interval * 100;
90:     let phase = 0, phaseScore = -1;
91:     const scan = Math.min(lag, frames - 2);
92:     for (let p = 0; p < scan; p += 2) {
93:       let sum = 0;
94:       for (let i = p; i < frames; i += lag) {
95:         const idx = Math.round(i);
96:         if (idx < frames) sum += novelty[idx];
97:       }
98:       if (sum > phaseScore) { phaseScore = sum; phase = p / 100; }
99:     }
100:     // Snap the regular beat grid to nearby onset peaks while preserving a playable tempo.
101:     const beats = [];
102:     for (let t = phase; t < buffer.duration; t += interval) {
