107:       }
108:       beats.push(beats.length ? Math.max(beats[beats.length - 1] + interval * .72, best) : best);
109:     }
110:     const confidence = bestScore > 0 ? Math.max(0, Math.min(99, Math.round(42 + (bestScore / Math.max(.0000001, runnerUp) - 1) * 35))) : 0;
